import math
from sympy import symbols, sympify, solve, expand, simplify, diff, integrate, Rational, sqrt, cos, sin, pi

t, theta, X = symbols("t theta X")


def work(line):
    parts = line.split()
    kind = parts[0]
    a = [sympify(w) for w in parts[1:]]
    print(line)
    if kind == "eliminate":
        s = solve(a[0] - X, t)[0]
        print(f"  t = {s}, so y = {expand(a[1].subs(t, s))}, with X for x")
    elif kind == "slope":
        x, y, t0 = a[0], a[1], a[2]
        dx, dy = diff(x, t).subs(t, t0), diff(y, t).subs(t, t0)
        print(f"  point ({x.subs(t, t0)}, {y.subs(t, t0)}), dx/dt = {dx}, dy/dt = {dy}")
        if dx == 0 and dy == 0:
            print("  both rates are 0: no slope from the formula")
        elif dx == 0:
            print("  dx/dt = 0: a vertical tangent")
        else:
            print(f"  slope {simplify(dy / dx)}")
    elif kind == "point":
        r = a[0].subs(theta, a[1])
        print(f"  r = {r}, point ({simplify(r * cos(a[1]))}, {simplify(r * sin(a[1]))})")
    elif kind == "rose":
        size, n = a[0], a[1]
        if n % 2 == 1:
            print(f"  n = {n} is odd: {n} petals of length {abs(size)}, theta from 0 to pi")
        else:
            print(f"  n = {n} is even: {2 * n} petals of length {abs(size)}, theta from 0 to 2pi")
    elif kind == "limacon":
        p, q = a[0], a[1]
        if p < q:
            c = math.acos(float(-p / q))
            print(f"  a = {p} < b = {q}: an inner loop, r = 0 at {c:.4f} and {2 * math.pi - c:.4f}")
        elif p == q:
            print(f"  a = b = {p}: a cardioid")
        elif p < 2 * q:
            print(f"  b = {q} < a = {p} < 2b = {2 * q}: a dimple, smallest r = {p - q}")
        else:
            print(f"  a = {p} >= 2b = {2 * q}: convex, smallest r = {p - q}")
    elif kind == "area":
        A = integrate(Rational(1, 2) * a[0]**2, (theta, a[1], a[2]))
        print(f"  1/2 * integral of ({a[0]})^2 = {A}, about {float(A):.4f}")
    elif kind == "length":
        speed = simplify(diff(a[0], t)**2 + diff(a[1], t)**2)
        print(f"  x'^2 + y'^2 = {speed}, length {integrate(sqrt(speed), (t, a[2], a[3]))}")


for line in ["eliminate 2*t-1 3-t", "rose 5 4", "slope t**2+1 t**3-t 2", "area 4*cos(theta) 0 pi",
             "limacon 5 3", "point 4*cos(theta) 3*pi/4", "length 1+5*t 2-12*t 0 1", "rose 3 3",
             "limacon 1 3", "slope t**3 t**2 0", "length 2*cos(2*t) 2*sin(2*t) 0 pi"]:
    work(line)

