from sympy import symbols, sympify, solve, simplify, diff, integrate, Rational, sqrt, cos, sin, pi, acos

t, theta = symbols("t theta")


def where(x, y, ts):
    if not ts:
        return "none"
    return ", ".join(f"t = {c} at ({simplify(x.subs(t, c))}, {simplify(y.subs(t, c))})" for c in ts)


def work(line):
    parts = line.split()
    kind = parts[0]
    a = [sympify(w) for w in parts[1:]]
    print(line)
    if kind == "tangents":
        x, y = a[0], a[1]
        flat = [c for c in solve(diff(y, t), t) if diff(x, t).subs(t, c) != 0]
        steep = [c for c in solve(diff(x, t), t) if diff(y, t).subs(t, c) != 0]
        print("  horizontal: " + where(x, y, flat))
        print("  vertical: " + where(x, y, steep))
    elif kind == "concavity":
        x, y, t0 = a[0], a[1], a[2]
        d1 = simplify(diff(y, t) / diff(x, t))
        d2 = simplify(diff(d1, t) / diff(x, t))
        v = d2.subs(t, t0)
        print(f"  dy/dx = {d1}, d2y/dx2 = {d2}")
        if v > 0:
            print(f"  at t = {t0}: {v} > 0, concave up")
        elif v < 0:
            print(f"  at t = {t0}: {v} < 0, concave down")
        else:
            print(f"  at t = {t0}: 0, no concavity there")
    elif kind == "onpoint":
        x, y, p, q = a[0], a[1], a[2], a[3]
        hits = [c for c in solve(x - p, t) if simplify(y.subs(t, c) - q) == 0]
        if len(hits) > 1:
            print(f"  on the curve at t = {hits}: it crosses itself there")
        elif hits:
            print(f"  on the curve at t = {hits[0]} only")
        else:
            print(f"  x = {p} at t = {solve(x - p, t)}, but y is never {q} there: not on the curve")
    elif kind == "polarslope":
        f, t0 = a[0], a[1]
        dx = simplify(diff(f * cos(theta), theta).subs(theta, t0))
        dy = simplify(diff(f * sin(theta), theta).subs(theta, t0))
        print(f"  f = {f.subs(theta, t0)}, f' = {diff(f, theta).subs(theta, t0)}, dx/dtheta = {dx}, dy/dtheta = {dy}")
        if dx == 0 and dy == 0:
            print("  both are 0: a cusp, no slope from the formula")
        elif dx == 0:
            print("  only dx/dtheta is 0: a vertical tangent")
        else:
            print(f"  slope {simplify(dy / dx)}")
    elif kind == "circle":
        p, q = a[0], a[1]
        print(f"  x^2 + y^2 = ({p})x + ({q})y: center ({p / 2}, {q / 2}), radius {sqrt(p**2 + q**2) / 2}")
    elif kind == "petal":
        size, n = a[0], a[1]
        one = integrate(Rational(1, 2) * (size * cos(n * theta))**2, (theta, -pi / (2 * n), pi / (2 * n)))
        petals = n
        if n % 2 == 0:
            petals = 2 * n
        print(f"  r = 0 at {-pi / (2 * n)} and {pi / (2 * n)}: one petal {one}, and {petals} petals: {petals * one}")
    elif kind == "inner":
        p, q = a[0], a[1]
        c = acos(-p / q)
        A = simplify(integrate(Rational(1, 2) * (p + q * cos(theta))**2, (theta, c, 2 * pi - c)))
        print(f"  r < 0 from {c} to {2 * pi - c}: area {A}, about {float(A):.4f}")


for line in ["tangents t**2-2*t t**3-12*t", "circle 4 -2", "petal 2 3", "concavity t**2 t**3+t 1",
             "polarslope 1+2*cos(theta) pi/3", "onpoint t**2-1 t**3-t 3 6", "onpoint t**2-1 t**3-t 0 0",
             "inner 2 4", "tangents t-sin(t) 1-cos(t)", "polarslope 1+cos(theta) pi"]:
    work(line)

