import math
from sympy import symbols, sympify, integrate, Rational, cos, pi

theta = symbols("theta")


def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3


def spiral(t):
    # the antiderivative of sqrt(t^2 + 1)
    return 0.5 * (t * math.sqrt(t * t + 1) + math.log(t + math.sqrt(t * t + 1)))


def work(line):
    parts = line.split()
    kind = parts[0]
    a = [sympify(w) for w in parts[1:]]
    print(line)
    if kind == "kick":
        u, v = float(a[0]), float(a[1])
        T = 2 * v / 9.8
        print(f"  lands at t = {T:.4f} s, {u * T:.4f} m away, top {v * v / (2 * 9.8):.4f} m at t = {T / 2:.4f}")
        L = simpson(lambda t: math.sqrt(u * u + (v - 9.8 * t)**2), 0, T, 100)
        print(f"  lands at slope {-v / u:.4f}, {math.degrees(math.atan(-v / u)):.2f} degrees, path {L:.4f} m")
    elif kind == "wheel":
        r, k = float(a[0]), float(a[1])
        print(f"  the bike goes {k * 2 * math.pi * r:.4f} m, the valve {k * 8 * r:.4f} m")
    elif kind == "radar":
        d, deg = float(a[0]), float(a[1])
        print(f"  r = {d} csc(theta) = {d / math.sin(math.radians(deg)):.4f} km at {deg} degrees")
    elif kind == "sprinkler":
        A = integrate(Rational(1, 2) * (a[0] + a[1] * cos(theta))**2, (theta, 0, 2 * pi))
        print(f"  area {A}, about {float(A):.4f}, against {pi * a[0]**2} for the circle r = {a[0]}")
    elif kind == "lawn":
        R, c = a[0], a[1]
        if 2 * c > R:
            print(f"  the pond reaches r = {2 * c}, past the park's edge at {R}")
        else:
            A = integrate(Rational(1, 2) * (R**2 - (c * (1 + cos(theta)))**2), (theta, 0, 2 * pi))
            print(f"  lawn {A}, about {float(A):.4f}")
    elif kind == "hose":
        c, k = float(a[0]), float(a[1])
        L = simpson(lambda t: math.sqrt((c * t)**2 + c * c), 0, 2 * math.pi * k, 200)
        print(f"  {c} * spiral(2pi * {k}) = {c * spiral(2 * math.pi * k):.4f} m, Simpson {L:.4f} m")
    elif kind == "track":
        p, q = float(a[0]), float(a[1])
        L = simpson(lambda t: math.sqrt((p * math.sin(t))**2 + (q * math.cos(t))**2), 0, 2 * math.pi, 100)
        print(f"  Simpson {L:.4f} m, between {2 * math.pi * min(p, q):.4f} and {2 * math.pi * max(p, q):.4f}")


for line in ["kick 12 9.8", "wheel 0.3 5", "radar 8 30", "sprinkler 5 2", "lawn 12 6",
             "hose 0.03 4", "track 60 30", "lawn 10 6"]:
    work(line)

